import json
# test parse_constant / parse_float behavior with C scanner
def pf(s): raise ValueError('float '+s)
def pc(s): raise ValueError('const '+s)
for txt in ['{\"a\": NaN}', '{\"a\": Infinity}', '{\"a\": 1.5}', '{\"a\": 1e2}', '{\"a\": 1.0}', '{\"a\": 1}']:
    try:
        r = json.loads(txt, parse_float=pf, parse_constant=pc)
        print(repr(txt), '->', r)
    except Exception as e:
        print(repr(txt), '-> EXC', type(e).__name__, e)
"

python3 -c "
import json
# duplicate keys detection via object_pairs_hook
def hook(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError('dup')
        d[k]=v
    return d
print(json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=hook))
try:
    json.loads('{\"a\":1,\"a\":2}')
except Exception as e: print('no hook exc')
# huge int
try:
    print(json.loads('[' + '1'*5000 + ']'))
except Exception as e:
    print('huge int ->', type(e).__name__, str(e)[:80])
# trailing garbage / whitespace
print(json.loads('  {}  '))
try:
    print(json.loads('{} x'))
except Exception as e: print('trailing ->', type(e).__name__)
"

